`timescale 1ns / 1ps
`default_nettype none
`include "tb_check.svh"

// pll.sv is generated by ecppll; this checks its EHXPLLL configuration through
// the behavioural model in tbs/models/EHXPLLL.v (which also enforces the ECP5
// PFD/VCO/output frequency ranges): 25 MHz in -> 125 MHz out, locked.
module tb_pll;
    logic clkin = 1'b0;
    always #20 clkin = ~clkin;   // 25 MHz

    wire clkout0, locked;

    pll dut (.clkin(clkin), .clkout0(clkout0), .locked(locked));

    int checks = 0;

    initial begin : main
        realtime t_rise, t_fall, t_prev;
        int      out_edges;

        #1;
        `CHECK(locked === 1'b0, ("locked=%b at power-up", locked))

        // Lock within 1 us (25 reference cycles).
        fork
            wait (locked === 1'b1);
            begin
                #1us;
                $fatal(1, "PLL did not lock within 1 us");
            end
        join_any
        disable fork;
        checks++;

        // 125 MHz: 8 ns period, 50% duty, 200 consecutive cycles.
        @(posedge clkout0);
        t_prev = $realtime;
        for (int i = 0; i < 200; i++) begin
            @(negedge clkout0);
            t_fall = $realtime;
            @(posedge clkout0);
            t_rise = $realtime;
            `CHECK(t_rise - t_prev == 8.0, ("clkout0 period %0.3f ns, expected 8.000", t_rise - t_prev))
            `CHECK(t_fall - t_prev == 4.0, ("clkout0 high time %0.3f ns, expected 4.000", t_fall - t_prev))
            `CHECK(locked === 1'b1, ("lock lost at %0t", $time))
            t_prev = t_rise;
        end

        // Exactly 5 output cycles per reference cycle, phase-aligned.
        for (int i = 0; i < 20; i++) begin
            @(posedge clkin);
            #0.1;
            `CHECK(clkout0 === 1'b1, ("clkout0 not rising with clkin (cycle %0d)", i))
            out_edges = 0;
            fork
                forever begin
                    @(posedge clkout0);
                    out_edges++;
                end
                @(posedge clkin);
            join_any
            disable fork;
            `CHECK(out_edges == 4, ("%0d clkout0 rising edges between clkin edges, expected 4", out_edges))
        end

        $display("PASS tb_pll: %0d checks", checks);
        $finish;
    end

    initial begin
        #100us;
        $fatal(1, "timeout");
    end

    `DUMP_WAVES(tb_pll)
endmodule

`default_nettype wire
